import React, { useState, useEffect, useMemo } from 'react';
import {
  Sun, CloudSun, Cloud, CloudRain, CloudSnow, CloudLightning, CloudFog,
  Wind, Droplets, RefreshCw,
} from 'lucide-react';

// ---------------------------------------------------------------------------
// Weather Outlook — today's conditions plus a multi-day forecast.
//
// This component SIMULATES forecast data locally so it works standalone.
// To wire it to a real source, replace `generateForecast()` with a fetch to
// a weather API, e.g. Open-Meteo (no key required):
//
//   const res = await fetch(
//     `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}` +
//     `&daily=weathercode,temperature_2m_max,temperature_2m_min,precipitation_probability_max` +
//     `&current_weather=true&timezone=auto`
//   );
//   const data = await res.json();
//
// then map `data.daily.*` arrays into the `days` shape used below.
// ---------------------------------------------------------------------------

const CONDITIONS = [
  { key: 'clear', label: 'Klar', Icon: Sun, color: 'var(--warm)' },
  { key: 'partly', label: 'Leicht bewölkt', Icon: CloudSun, color: 'var(--warm)' },
  { key: 'cloudy', label: 'Bewölkt', Icon: Cloud, color: 'var(--text-dim)' },
  { key: 'rain', label: 'Regen', Icon: CloudRain, color: 'var(--cool)' },
  { key: 'storm', label: 'Gewitter', Icon: CloudLightning, color: 'var(--alert)' },
  { key: 'snow', label: 'Schnee', Icon: CloudSnow, color: 'var(--cool)' },
  { key: 'fog', label: 'Nebel', Icon: CloudFog, color: 'var(--text-dim)' },
];

const WEEKDAYS = ['So', 'Mo', 'Di', 'Mi', 'Do', 'Fr', 'Sa'];

function pick(arr, seed) {
  return arr[Math.floor(seed) % arr.length];
}

function generateForecast(days = 6) {
  const today = new Date();
  let baseHigh = 21 + Math.random() * 6;
  let baseLow = baseHigh - (6 + Math.random() * 4);
  const out = [];
  for (let i = 0; i < days; i++) {
    const date = new Date(today);
    date.setDate(today.getDate() + i);
    baseHigh += (Math.random() - 0.5) * 3.5;
    baseLow += (Math.random() - 0.5) * 2.5;
    if (baseLow > baseHigh - 3) baseLow = baseHigh - 3;
    const precip = Math.max(0, Math.min(100, Math.round(
      (baseLow < 14 ? 35 : 10) + (Math.random() - 0.4) * 60
    )));
    let condKey = 'clear';
    if (precip > 70) condKey = Math.random() > 0.7 ? 'storm' : 'rain';
    else if (precip > 40) condKey = 'rain';
    else if (precip > 20) condKey = 'cloudy';
    else condKey = Math.random() > 0.5 ? 'partly' : 'clear';
    if (baseLow < 1 && precip > 30) condKey = 'snow';
    const cond = CONDITIONS.find((c) => c.key === condKey) || CONDITIONS[0];
    out.push({
      date,
      weekday: i === 0 ? 'Heute' : WEEKDAYS[date.getDay()],
      high: Math.round(baseHigh),
      low: Math.round(baseLow),
      precip,
      wind: Math.round(6 + Math.random() * 18),
      humidity: Math.round(40 + Math.random() * 35),
      condition: cond,
    });
  }
  return out;
}

function formatDate(d) {
  return d.toLocaleDateString('de-DE', { weekday: undefined, day: '2-digit', month: 'short' });
}

export default function WeatherOutlook() {
  const [days, setDays] = useState(() => generateForecast(6));
  const [updatedAt, setUpdatedAt] = useState(new Date());
  const [spinning, setSpinning] = useState(false);

  // Simulated periodic refresh — swap for a real API poll.
  useEffect(() => {
    const t = setInterval(() => {
      setDays(generateForecast(6));
      setUpdatedAt(new Date());
    }, 45000);
    return () => clearInterval(t);
  }, []);

  const refresh = () => {
    setSpinning(true);
    setDays(generateForecast(6));
    setUpdatedAt(new Date());
    setTimeout(() => setSpinning(false), 600);
  };

  const weekRange = useMemo(() => {
    const lows = days.map((d) => d.low);
    const highs = days.map((d) => d.high);
    return [Math.min(...lows), Math.max(...highs)];
  }, [days]);

  const today = days[0];
  const upcoming = days.slice(1);

  return (
    <div className="wx-root">
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;700&display=swap');

        .wx-root {
          --bg: #15181b;
          --panel: #1c2024;
          --panel-raised: #21262b;
          --line: #2a3136;
          --text: #edeff1;
          --text-dim: #838d94;
          --text-faint: #4d565c;
          --warm: #ff8f5e;
          --warm-dim: #ff8f5e33;
          --cool: #52c7e0;
          --cool-dim: #52c7e033;
          --alert: #f2c744;
          --radius: 10px;
          font-family: 'Space Grotesk', -apple-system, sans-serif;
          background: var(--bg);
          color: var(--text);
          padding: 28px;
          min-height: 100%;
          box-sizing: border-box;
        }
        .wx-root * { box-sizing: border-box; }
        .wx-mono { font-family: 'JetBrains Mono', ui-monospace, monospace; }

        .wx-header {
          display: flex;
          align-items: flex-start;
          justify-content: space-between;
          margin-bottom: 22px;
          padding-bottom: 16px;
          border-bottom: 1px solid var(--line);
          flex-wrap: wrap;
          gap: 10px;
        }
        .wx-eyebrow {
          font-size: 11px;
          letter-spacing: 0.16em;
          color: var(--text-faint);
          text-transform: uppercase;
        }
        .wx-title {
          font-size: 20px;
          font-weight: 700;
          letter-spacing: 0.02em;
          margin-top: 2px;
        }
        .wx-refresh {
          display: flex;
          align-items: center;
          gap: 6px;
          font-size: 11px;
          color: var(--text-dim);
          background: none;
          border: 1px solid var(--line);
          border-radius: 999px;
          padding: 6px 12px;
          cursor: pointer;
          transition: border-color 0.15s, color 0.15s;
        }
        .wx-refresh:hover { border-color: var(--text-faint); color: var(--text); }
        .wx-refresh:focus-visible { outline: 2px solid var(--cool); outline-offset: 2px; }
        .wx-refresh svg { transition: transform 0.6s ease; }
        .wx-refresh.spin svg { transform: rotate(360deg); }

        .wx-today {
          background: var(--panel);
          border: 1px solid var(--line);
          border-radius: var(--radius);
          padding: 22px 24px;
          display: grid;
          grid-template-columns: auto 1fr auto;
          align-items: center;
          gap: 20px;
          margin-bottom: 14px;
        }
        @media (max-width: 640px) {
          .wx-today { grid-template-columns: auto 1fr; }
          .wx-today-stats { grid-column: 1 / -1; }
        }
        .wx-today-icon {
          width: 64px; height: 64px;
          border-radius: 50%;
          background: var(--panel-raised);
          display: flex; align-items: center; justify-content: center;
          flex-shrink: 0;
        }
        .wx-today-main { min-width: 0; }
        .wx-today-date { font-size: 12px; color: var(--text-dim); margin-bottom: 2px; }
        .wx-today-temp-row { display: flex; align-items: baseline; gap: 10px; }
        .wx-today-temp { font-size: 42px; font-weight: 500; line-height: 1; }
        .wx-today-cond { font-size: 14px; color: var(--text-dim); }
        .wx-today-stats {
          display: flex;
          flex-direction: column;
          gap: 8px;
          font-size: 12px;
          color: var(--text-dim);
          border-left: 1px solid var(--line);
          padding-left: 20px;
        }
        .wx-today-stat { display: flex; align-items: center; gap: 6px; }
        .wx-today-stat .wx-mono { color: var(--text); }

        .wx-list {
          background: var(--panel);
          border: 1px solid var(--line);
          border-radius: var(--radius);
          overflow: hidden;
        }
        .wx-row {
          display: grid;
          grid-template-columns: 64px 32px 1fr 46px minmax(90px, 1fr) 58px;
          align-items: center;
          gap: 14px;
          padding: 13px 20px;
          border-bottom: 1px solid var(--line);
        }
        .wx-row:last-child { border-bottom: none; }
        @media (max-width: 560px) {
          .wx-row { grid-template-columns: 50px 26px 1fr 40px 70px 46px; gap: 8px; padding: 12px 14px; }
          .wx-row-cond { display: none; }
        }
        .wx-row-day { font-size: 13px; font-weight: 500; }
        .wx-row-date { font-size: 10px; color: var(--text-faint); display: block; }
        .wx-row-cond { font-size: 12px; color: var(--text-dim); }
        .wx-row-precip {
          display: flex; align-items: center; gap: 4px;
          font-size: 11px; color: var(--cool);
          justify-self: end;
        }
        .wx-range { display: flex; align-items: center; gap: 8px; }
        .wx-range-low, .wx-range-high { font-size: 12px; width: 26px; }
        .wx-range-low { color: var(--text-dim); text-align: right; }
        .wx-range-high { color: var(--text); }
        .wx-range-track {
          position: relative;
          flex: 1;
          height: 4px;
          background: var(--panel-raised);
          border-radius: 999px;
        }
        .wx-range-fill {
          position: absolute;
          top: 0; bottom: 0;
          border-radius: 999px;
          background: linear-gradient(90deg, var(--cool), var(--warm));
        }
      `}</style>

      <header className="wx-header">
        <div>
          <div className="wx-eyebrow">Wetterprognose</div>
          <div className="wx-title">Nächste Tage</div>
        </div>
        <button className={`wx-refresh ${spinning ? 'spin' : ''}`} onClick={refresh}>
          <RefreshCw size={12} strokeWidth={2} />
          <span className="wx-mono">{updatedAt.toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' })}</span>
        </button>
      </header>

      {today && (
        <div className="wx-today">
          <div className="wx-today-icon">
            <today.condition.Icon size={30} color={today.condition.color} strokeWidth={1.6} />
          </div>
          <div className="wx-today-main">
            <div className="wx-today-date">{formatDate(today.date)} · Heute</div>
            <div className="wx-today-temp-row">
              <span className="wx-today-temp wx-mono">{today.high}°</span>
              <span className="wx-today-cond">{today.condition.label}, Tief {today.low}°</span>
            </div>
          </div>
          <div className="wx-today-stats">
            <div className="wx-today-stat">
              <Wind size={13} strokeWidth={2} />
              <span className="wx-mono">{today.wind} km/h</span>
            </div>
            <div className="wx-today-stat">
              <Droplets size={13} strokeWidth={2} />
              <span className="wx-mono">{today.humidity}%</span>
              <span>Luftfeuchte</span>
            </div>
          </div>
        </div>
      )}

      <div className="wx-list">
        {upcoming.map((d, i) => {
          const [rangeMin, rangeMax] = weekRange;
          const span = Math.max(rangeMax - rangeMin, 1);
          const left = ((d.low - rangeMin) / span) * 100;
          const width = ((d.high - d.low) / span) * 100;
          return (
            <div className="wx-row" key={i}>
              <div>
                <span className="wx-row-day">{d.weekday}</span>
                <span className="wx-row-date wx-mono">{formatDate(d.date)}</span>
              </div>
              <d.condition.Icon size={18} color={d.condition.color} strokeWidth={1.8} />
              <span className="wx-row-cond">{d.condition.label}</span>
              <span className="wx-row-precip wx-mono">
                <Droplets size={11} strokeWidth={2} />
                {d.precip}%
              </span>
              <div className="wx-range">
                <span className="wx-range-low wx-mono">{d.low}°</span>
                <div className="wx-range-track">
                  <div className="wx-range-fill" style={{ left: `${left}%`, width: `${width}%` }} />
                </div>
              </div>
              <span className="wx-range-high wx-mono">{d.high}°</span>
            </div>
          );
        })}
      </div>
    </div>
  );
}
